<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <main id="maincontent" tabindex="-1">
    <section class="support-shell" aria-labelledby="support-title">
      <div class="support-copy">
        <div>
          <p class="eyebrow">Support</p>
          <h1 id="support-title">Get help from our product team.</h1>
          <p class="lead">Share your contact details and our support specialists will follow up with the right next step for your account, billing, or technical question.</p>
        </div>

        <ul class="benefits" aria-label="Support response highlights">
          <li>
            <div>
              <strong>Fast triage</strong>
              Clear contact details help route requests to the right specialist.
            </div>
          </li>
          <li>
            <div>
              <strong>Human follow-up</strong>
              Required fields make sure we can reach you without extra back-and-forth.
            </div>
          </li>
          <li>
            <div>
              <strong>Phone optional</strong>
              Add a number only if you want help by call or text.
            </div>
          </li>
        </ul>
      </div>

      <div class="support-card">
        <form id="support-form" novalidate>
          <p class="required-note">Fields marked <span class="required-mark" aria-hidden="true">*</span> are required.</p>

          <div class="form-field">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
              aria-errormessage="full-name-error"
            >
            <p id="full-name-error" class="error-message" hidden></p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              inputmode="email"
              autocomplete="email"
              required
              aria-describedby="email-error"
              aria-errormessage="email-error"
              placeholder="name@example.com"
            >
            <p id="email-error" class="error-message" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              aria-describedby="phone-help phone-error"
              aria-errormessage="phone-error"
              placeholder="+1 555 123 4567"
            >
            <p id="phone-help" class="helper-text">Expected format: +1 555 123 4567. You can also use spaces, dashes, or parentheses.</p>
            <p id="phone-error" class="error-message" hidden></p>
          </div>

          <div class="actions">
            <button type="submit">Send to support</button>
            <p id="form-status" class="status-message" aria-live="polite"></p>
          </div>
        </form>
      </div>
    </section>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");

    const fields = {
      fullName: {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Error: Enter your full name.";
          }

          return "";
        }
      },
      email: {
        input: document.getElementById("email"),
        error: document.getElementById("email-error"),
        validate(value) {
          if (!value.trim()) {
            return "Error: Enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Error: Enter a valid email address, such as name@example.com.";
          }

          return "";
        }
      },
      phone: {
        input: document.getElementById("phone"),
        error: document.getElementById("phone-error"),
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return "";
          }

          const phonePattern = /^\+?[0-9().\s-]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return "Error: Enter a valid phone number in the format +1 555 123 4567.";
          }

          return "";
        }
      }
    };

    function updateFieldState(fieldConfig) {
      const message = fieldConfig.validate(fieldConfig.input.value);
      const hasError = Boolean(message);

      fieldConfig.input.setAttribute("aria-invalid", hasError ? "true" : "false");
      fieldConfig.error.textContent = message;
      fieldConfig.error.hidden = !hasError;

      return hasError;
    }

    Object.values(fields).forEach((fieldConfig) => {
      fieldConfig.input.addEventListener("blur", () => {
        updateFieldState(fieldConfig);
      });

      fieldConfig.input.addEventListener("input", () => {
        if (fieldConfig.input.getAttribute("aria-invalid") === "true") {
          updateFieldState(fieldConfig);
        }

        if (statusMessage.textContent) {
          statusMessage.textContent = "";
          statusMessage.removeAttribute("data-state");
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const invalidField = Object.values(fields).find((fieldConfig) => updateFieldState(fieldConfig));

      if (invalidField) {
        statusMessage.textContent = "Please correct the highlighted fields and try again.";
        statusMessage.removeAttribute("data-state");
        invalidField.input.focus();
        return;
      }

      statusMessage.textContent = "Thanks. Your support request details were sent successfully.";
      statusMessage.setAttribute("data-state", "success");
      form.reset();
      Object.values(fields).forEach((fieldConfig) => {
        fieldConfig.input.setAttribute("aria-invalid", "false");
        fieldConfig.error.hidden = true;
        fieldConfig.error.textContent = "";
      });
      fields.fullName.input.focus();
    });
  </script>
</body>
</html>
