394.   <script>
395.     const form = document.getElementById("support-form");
396.     const statusMessage = document.getElementById("form-status");
397. 
398.     const fields = {
399.       fullName: {
400.         input: document.getElementById("full-name"),
401.         error: document.getElementById("full-name-error"),
402.         validate(value) {
403.           if (!value.trim()) {
404.             return "Error: Enter your full name.";
405.           }
406. 
407.           return "";
408.         }
409.       },
410.       email: {
411.         input: document.getElementById("email"),
412.         error: document.getElementById("email-error"),
413.         validate(value) {
414.           if (!value.trim()) {
415.             return "Error: Enter your email address.";
416.           }
417. 
418.           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
419.           if (!emailPattern.test(value.trim())) {
420.             return "Error: Enter a valid email address, such as name@example.com.";
421.           }
422. 
423.           return "";
424.         }
425.       },
426.       phone: {
427.         input: document.getElementById("phone"),
428.         error: document.getElementById("phone-error"),
429.         validate(value) {
430.           const trimmedValue = value.trim();
431.           if (!trimmedValue) {
432.             return "";
433.           }
434. 
435.           const phonePattern = /^\+?[0-9().\s-]{7,20}$/;
436.           if (!phonePattern.test(trimmedValue)) {
437.             return "Error: Enter a valid phone number in the format +1 555 123 4567.";
438.           }
439. 
440.           return "";
441.         }
442.       }
443.     };
444. 
445.     function updateFieldState(fieldConfig) {
446.       const message = fieldConfig.validate(fieldConfig.input.value);
447.       const hasError = Boolean(message);
448. 
449.       fieldConfig.input.setAttribute("aria-invalid", hasError ? "true" : "false");
450.       fieldConfig.error.textContent = message;
451.       fieldConfig.error.hidden = !hasError;
452. 
453.       return hasError;
454.     }
455. 
456.     Object.values(fields).forEach((fieldConfig) => {
457.       fieldConfig.input.addEventListener("blur", () => {
458.         updateFieldState(fieldConfig);
459.       });
460. 
461.       fieldConfig.input.addEventListener("input", () => {
462.         if (fieldConfig.input.getAttribute("aria-invalid") === "true") {
463.           updateFieldState(fieldConfig);
464.         }
465. 
466.         if (statusMessage.textContent) {
467.           statusMessage.textContent = "";
468.           statusMessage.removeAttribute("data-state");
469.         }
470.       });
471.     });
472. 
473.     form.addEventListener("submit", (event) => {
474.       event.preventDefault();
475. 
476.       const invalidField = Object.values(fields).find((fieldConfig) => updateFieldState(fieldConfig));
477. 
478.       if (invalidField) {
479.         statusMessage.textContent = "Please correct the highlighted fields and try again.";
480.         statusMessage.removeAttribute("data-state");
481.         invalidField.input.focus();
482.         return;
483.       }
484. 
485.       statusMessage.textContent = "Thanks. Your support request details were sent successfully.";
486.       statusMessage.setAttribute("data-state", "success");
487.       form.reset();
488.       Object.values(fields).forEach((fieldConfig) => {
489.         fieldConfig.input.setAttribute("aria-invalid", "false");
490.         fieldConfig.error.hidden = true;
491.         fieldConfig.error.textContent = "";
492.       });
493.       fields.fullName.input.focus();
494.     });
495.   </script>
